(()=>{'use strict';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));async function req(url,method='GET'){const r=await fetch(url,{method,credentials:'same-origin'}),j=await r.json();if(!r.ok)throw Error(j.error||'Помилка');return j;}async function init(){const a=await req('/api/accounts');$('#users').innerHTML='<table class="account-table"><thead><tr><th>Логін</th><th>Роль</th><th>Профіль</th></tr></thead><tbody>'+a.accounts.map(u=>`<tr><td>${esc(u.username)}</td><td>${u.role==='operator'?'Оператор':'Астронавт'}</td><td>${esc(u.crewName||'Весь екіпаж')}</td></tr>`).join('')+'</tbody></table>';const reports=(await req('/api/reports')).reports;$('#reports').innerHTML=reports.length?reports.map(r=>`<div class="report-card"><b>${esc(a.crew.find(c=>c.id===r.crewId)?.name)}</b> · ${esc(r.at)} · Сон ${r.sleep} год · Самопочуття ${r.mood}/5${r.notes?`<p>${esc(r.notes)}</p>`:''}</div>`).join(''):'Записів поки немає.';}$('#logout').onclick=async()=>{await req('/api/auth/logout','POST');location.replace('/login.html');};init().catch(e=>$('#users').textContent=e.message);})();
